\cite{MR1271864, MR3774803, MR3475564} \label{mainlambda1} For $1 \leq p \leq n-1$,
$$
\chi'_p(K_n) =
\begin{cases} 
      p+1 & \text{ if } $p$ \text{ even and } n \equiv p+1 \ (\mathrm{mod}\ 2p)\\
      p & \text{ otherwise.}
   \end{cases}
$$

\cite{MR3764373}
\label{bobservation}
Let $W$ be a $(2t+1,2t)$-edge-coloring of $K_n$ with the colors in $C$ for $n=4tx+2t+1$ for some integer $x$.
Then $b(n, W, u, i)= \frac{n-1}{2t}=2x+1$ for all $u \in V(K_n)$ and $i \in C$.

\label{mainquestbpreserved}
Let $1 \leq t_1 < t_2$ be integers and $b$ be an odd integer.
When can an equitable $(2t_1+1, 2t_1)$-edge-coloring of $K_{n_1}$ be embedded in an equitable $(2t_2+1, 2t_2)$-edge-coloring of $K_{n_2}$ where $n_1=2t_1b+1$ and $n_2=2t_2b+1$?

\label{thm:b(n)=1}
If $b=1$, an equitable $(2t_1+1, 2t_1)$-edge-coloring of $K_{n_1}$
can be embedded in an equitable $(2t_2+1, 2t_2)$-edge-coloring of $K_{n_2}$ if and only if $t_1 \leq 2t_2$.

\label{obs:Old-color-method-theorem}
Let $t_2 = 2t_1$.
An equitable $(2t_1+1, 2t_1)$-edge-coloring of $K_{n_1}$ can be embedded in an equitable $(2t_2+1, 2t_2)$-edge-coloring of $K_{n_2}$.

\label{obs:New-color-method-theorem}
Let $2t_1 <t_2 < 4t_1$.
An equitable $(2t_1+1, 2t_1)$-edge-coloring of $K_{n_1}$ can be embedded in an equitable $(2t_2+1, 2t_2)$-edge-coloring of $K_{n_2}$.

Recall that $m= \vert C_N \vert = 2t_2-2t_1$.
Let $X = \{x_1, x_2, \dots x_{n_1}\}$ and $Y= \{y_{0}, y_{1}, \dots y_{m-1}\}$.
We will form edge-colored graphs $G_1, G_2, \dots G_6$ on the vertex set $X \cup Y$ as follows.
Once this is done defining $G'= \cup_{i=1}^6 G_i$, Theorem \ref{amalgamationtheorem} will be used to detach $G'$ to form $G= K_{n_2}$ with our desired equitable $(2t_2+1,2t_2)$-edge-coloring and an arbitrary $(2t_1+1, 2t_1)$-edge-coloring of $K_{n_1}$ as a subgraph.
To do so, $\phi: V(G) \rightarrow V(G')$ will be the amalgamation function with amalgamation numbers $\eta(x_i)= 1$ for $1 \leq i \leq n_1$ and $\eta(y_p)= b$ for $ 0 \leq p \leq  m-1$.

We consider $2$ cases based on the parity of $a$ in the following equation.
These cases first differ when defining $G_3$ in (iii).
By the division algorithm there exists a unique $a$ and $r$ such that $0 \leq r \leq m-2$ and \begin{equation} \label{divalg}
n_1b = a (m-1) +r.
\end{equation}
Also, as we will need in (vi) in both cases,
\begin{equation} \label{a>2}
a > 2
\end{equation}
because
$$\begin{array}{lllll} 
a&=& \frac{n_1b-r}{m-1}&\phantom{W}&\text{By (\ref{divalg}})\\[3pt]
&>& \frac{n_1b}{m-1}-1& &\text{Because }r\leq m-2\\[3pt]

&=& \frac{(2t_1b+1)b}{2t_2-2t_1-1}-1\\[3pt]
&>& \frac{(2t_1b+1)b}{6t_1-1}-1& &\text{Because } t_2< 4t_1\\[3pt]
&\geq& \frac{(2t_1(3)+1)(3)}{6t_1-1}-1& &\text{Because } b\geq 3\\[3pt]
&=& (\frac{6t_1+1}{6t_1-1})3-1\\[3pt]
&>& (1)3-1\\[3pt]
&=& 2.
\end{array}$$
For clarity, the cases are written completely separately with notes where the two cases are the same.

\noindent
{\bf Case 1:} Assume $a$ is even.

\begin{enumerate}[i)]
\item Let $G_1=K_{n_1}$ on the vertex set $X$ with any $(2t_1+1, 2t_1)$-edge-coloring, call it $W_1$, using the colors in $C_O$ (such a coloring exists by Theorem \ref{mainlambda1}). Let $S_c$ be the set of vertices in $X$ missing color $c$ in $W_1$ for $1 \leq c \leq 2t_1+1$. 









\item Form $G_{2}=bK_{n_1,m}$ with parts $X$ and $Y$ using the following steps. For $y_p\in Y$, let color $s_1+1+p$ be missing from $y_p$.
For $x_i\in X$, we will color $b$ edges with color $s_1+1+p$ between $x_i$ and $Y$.
Informally, for $0 \leq p \leq m-1$, first color the edge $\{x_1, y_{p+1 \ (\mathrm{mod}\ m)}\}$ with color $s_1+1+p$ and then color the edge between $x_1$ and ``next" vertex in $Y$ skipping $y_p$ until there are $b$ edges of color $s_1+1+p$ between $x_1$ and $Y$.
Then color $b$ edges between $x_2$ and $Y$ by ``Picking up where we left off in $Y$".
Continue to do this until each vertex in $X$ has $b$ edges colored $s_1+1+p$ between it and $Y$.
Formally, for $x_i\in X$, color an edge $\{x_i,y_{p+h+1\ (\mathrm{mod}\ m)}\}$ with color $s_1+1+p$, where $h \equiv (j+(i-1)b)\ (\mathrm{mod}\ m-1)$ 

for $0 \leq p \leq m-1$ and $0\leq j\leq b-1$

(see Figure \ref{bipartex} (a)).
Note that each vertex $x_i \in X$ is incident to $b$ edges of color $s_1+1+p$, the vertices $y_{p+1 \ (\mathrm{mod}\ m)}, y_{p+2\ (\mathrm{mod}\ m)}, \dots ,y_{p+r \ (\mathrm{mod}\ m)}$ are incident to $a+1$ edges colored $s_1+1+p$, the vertices $y_{p+r+1 \ (\mathrm{mod}\ m)}, y_{p+r+2 \ (\mathrm{mod}\ m)}, \dots, y_{p-1 \ (\mathrm{mod}\ m)}$ are incident to $a$ edges colored $s_1+1+p$, and $y_p$ is incident to no edges colored $s_1+1+p$ (see Figure \ref{bipartex} (b)).

