\item Let $G_{4}=(b^2 - (a+1))K_m$ on the vertex set $Y$. Using Lemma \ref{Kdecomp}, decompose $G_{4}$ into $m\left(\frac{b^2-(a+1)}{2}\right)$ cycles of length $(m-1)$.
We color the edges of $G_4$ as follows.
For $0\leq p\leq m-1$, color the $\frac{b^2-(a+1)}{2}$ cycles with no edges incident to $y_p$ with color $s_1+1+p$ (This is possible because each cycle excludes exactly $1$ vertex $y_p \in Y$).
\item Using Lemma \ref{1factKn}, take a $1$-factorization of $K_m$ on the vertex set $Y$, producing $(m-1)$ edge-disjoint $1$-factors.
For each $k \in C_O$, create $F_{k}$  by coloring one distinct $1$-factor with color $k$.
This is possible because $m-1\geq 2t_1+1$
(Since $2t_1 <t_2$, $2t_1<2(t_2-t_1)=m$, and because $m$ is even, $m-1\geq 2t_1+1$).
Let $G_{5}=\bigcup_{k\in C_O}F_{k}$.
\item Let $H = b^2K_m$ on the vertex set $Y$ with $\frac{b(b-1)}{2}$ loops on each $y \in Y$.
Let $G_6 = H-(G_3 \cup G_4 \cup G_5)$.
We first check that $G_6$ exists (we have not removed nonexistent edges from $H$).
For each pair of vertices $y_p,y_s \in Y$ there are at most $2$ edges between $y_p$ and $y_s$ in $G_3$, exactly $b^2-(a+1)$ edges between $y_p$ and $y_s$ in $G_4$, and at most $1$ edge between $y_p$ and $y_s$ in $G_5$. The minimum number of edges between $y_p$ and $y_s$ in $G_6$ is $b^2-2-(b^2-(a+1))-1 = a-2$. By (\ref{a>2}), $a-2 > 0$, so $G_6$ exists.

The degree of each vertex in $H$ is $(b^2)(m-1)+b(b-1)$, in $G_3$ is $m-r-1$, in $G_4$ is $(b^2-(a+1))(m-1)$, and in $G_5$ is $2t_1+1$. Then, the degree of each vertex $y \in Y$ in $G_6$ is 

$\begin{array}{llll}
\deg_{G_6}(y) & = & \deg_{H}(y)-\deg_{G_3}(y)-\deg_{G_4}(y)-\deg_{G_5}(y) \\[4pt]
& = & b^2(m-1)+b(b-1)-(m-r-1)\\[4pt]
& & -(b^2-(a+1))(m-1))-(2t_1+1) \\[4pt]






&=& a(m-1)+r-(2t_1+1)+b(b-1)\\[4pt]
&=& n_1b-(2t_1+1)+b(b-1)& \text{By (\ref{divalg})}\\[4pt]
&=& (2t_1b+1)b-2t_1-1+b(b-1)\\[4pt]




&=& (2t_1+1)(b^2-1).\\
\end{array}$

By Theorem \ref{petersen}, $G_6$ can be partitioned into $\frac{(2t_1+1)(b^2-1)}{2}$ edge-disjoint $2$-factors. For $k\in C_O$, color $\frac{(b^2-1)}{2}$ distinct $2$-factors with color $k$.
\end{enumerate}

We define $G'=\bigcup_{i=1}^6G_i$. We will use Theorem \ref{amalgamationtheorem} to form the detachment $G=K_{n_2}$ with our desired equitable $(2t_2+1,2t_2)$-edge-coloring and an arbitrary equitable $(2t_1+1,2t_1)$-edge-coloring of $K_{n_1}$ as a subgraph. Recall that $\phi: V(G) \rightarrow V(G')$ is the amalgamation function with amalgamation numbers $\eta(x_i)= 1$ for $1 \leq i \leq n_1$ and $\eta(y_p)= b$ for $ 0 \leq p \leq  m-1$.

We first check that there are $b$ edges of each color incident to each vertex $v_i\in V_O$ except exactly one color in $C_O$. By (i), each $x_i\in X$ is missing some $c \in C_O$.

\begin{itemize}
\item For $k\in C_O\setminus \{c\}$, by (i), $deg_{G'(k)}(x_i)=b$. By Theorem \ref{amalgamationtheorem} (i), $deg_{G(k)}(v_i)=deg_{G'(k)}(x_i)/\eta(x_i)=b/1=b$ for $v_i\in \phi^{-1}(x_i)$.
\item For $k\in C_N$, by (ii), $deg_{G'(k)}(x_i)=b$. By Theorem \ref{amalgamationtheorem} (i), $deg_{G(k)}(v_i)=deg_{G'(k)}(x_i)/\eta(x_i)=b/1=b$ for $v_i\in \phi^{-1}(x_i)$.
\end{itemize}

We now check that each vertex $v_i\in V_N$ is incident to $b$ edges of each color $k$, except for exactly one color in $C_N$.

\begin{itemize}
\item For $k\in C_O$ and $y_p\in Y$, by (v) and (vi), $deg_{G'(k)}(y_p)=1+2\left(\frac{b^2-1}{2}\right)=b^2$. By Theorem \ref{amalgamationtheorem} (i), $deg_{G(k)}(v_i)=deg_{G'(k)}(y_p)/\eta(y_p)=b^2/b=b$ for $v_i\in \phi^{-1}(y_p)$.
\item For $k\in C_N\setminus \{p\}$ and $y_p\in Y$, by (ii), (iii), and (iv), $deg_{G'(k)}(y_p)=a+1+(b^2-(a+1))=b^2$. By Theorem \ref{amalgamationtheorem} (i), $deg_{G(k)}(v_i)=deg_{G'(k)}(y_p)/\eta(y_p)=b^2/b=b$ for $v_i\in \phi^{-1}(y_p)$.
\end{itemize}

We now check that $G=K_{n_2}$ by determining there is exactly one edge between each pair of vertices in $V(G)$.

\begin{itemize}
\item We first show there is exactly $1$ edge between each pair of vertices $v_i,v_j\in V_O$. For $x_i,x_j\in X$, by (i), $m_{G'}(x_i,x_j)=1$. By Theorem \ref{amalgamationtheorem} (iii), $m_G(v_i,v_j)=m_{G'}(x_i,x_j)/(\eta(x_i)\eta(x_j))=1/((1)(1))=1$ for $v_i\in \phi^{-1}(x_i)$ and $v_j\in \phi^{-1}(x_j)$.
\item We now show there is exactly $1$ edge between each pair of vertices $v_i\in V_O$ and $v_j\in V_N$. For $x_i\in X$ and $y_p\in Y$, by (ii), $m_{G'}(x_i,y_p)=b$. By Theorem \ref{amalgamationtheorem} (iii), $m_G(v_i,v_j)=m_{G'}(x_i,y_p)/(\eta(x_i)\eta(y_p))=b/((1)(b))=1$ for $v_i\in \phi^{-1}(x_i)$ and $v_j\in \phi^{-1}(y_p)$.
\item We now show there is exactly $1$ edge between each pair of vertices $v_i,v_j\in V_N$, where $v_i\in \phi^{-1}(y_p)$ and $v_j\in \phi^{-1}(y_s)$, and $y_p,y_s\in Y$. By (iii), (iv), (v), and (vi),
\[\begin{aligned}
m_{G'}(y_p,y_s) &= \sum_{i=3}^{6}m_{G_i}(y_p,y_s)\\
&= \sum_{i=3}^{5}m_{G_i}(y_p,y_s) + m_{G_6}(y_p,y_s)\\
&= \sum_{i=3}^{5}m_{G_i}(y_p,y_s) +b^2-\sum_{i=3}^{5}m_{G_i}(y_p,y_s))\\
&= b^2.
\end{aligned}\]
By Theorem \ref{amalgamationtheorem} (iii), $m_G(v_i,v_j)=m_{G'}(y_p,y_s)/(\eta(y_p)\eta(y_s))=b^2/((b)(b))=1$ for $v_i\in \phi^{-1}(y_p)$ and $v_j\in \phi^{-1}(y_s)$.
\item Finally, we show there is exactly $1$ edge between each pair of vertices $v_i,v_j\in V_N$, where $v_i,v_j\in \phi^{-1}(y_p)$ for $y_p \in Y$. By (vi), $\ell_{G'}(y_p)=\frac{b(b-1)}{2}={b \choose 2}={\eta(y_p) \choose 2}$. By Theorem \ref{amalgamationtheorem} (ii), $m_G(v_i,v_j)=\ell_{G'}(y_p)/{\eta(y_p)\choose 2}={\eta(y_p)\choose 2}/{\eta(y_p)\choose 2}=1$ for $v_i,v_j\in \phi^{-1}(y_p)$.
\end{itemize}

